const chatInput = String($json.chatInput ?? '').trim();
const codeLabel = /^\s*c[óo]digo\s*[:=\-]?\s*/i;
const codeShape = /^[\d\s.\-\/]+$/;
const withoutLabel = chatInput.replace(codeLabel, '').trim();
const codigoDigits = withoutLabel.replace(/\D/g, '');
const isCodeInput = codigoDigits.length >= 3 && codeShape.test(withoutLabel);

return [{
  json: {
    chat_input: chatInput,
    is_code_input: isCodeInput,
    codigo_digits: codigoDigits,
  },
}];

const digits = String($json.codigo_digits ?? '').trim();
const topK = Number($json.top_k);

if (!digits || !/^\d+$/.test(digits)) {
  throw new Error('Código sem dígitos para a busca por código.');
}
if (!Number.isInteger(topK) || topK < 1) {
  throw new Error('Search configuration is invalid: top_k must be a positive integer.');
}

return [{ json: { codigo_digits: digits, top_k: topK } }];

// Build the extract/route request body. Keeping it here means the HTTP node's
// expression stays a single JSON.stringify() without nested brace literals,
// which n8n's `{{ ... }}` parser would read as its own closing brackets.
const chatInput = String($json.chat_input ?? '').trim();
const SYSTEM_PROMPT = `Você classifica mensagens de servidores públicos que procuram a natureza de despesa correta.

Responda somente com JSON no formato {"intencao": "<intencao>", "termo_busca": "<termo>"}.

Intenções possíveis:
- "saudacao": APENAS cumprimentos e cortesias, como "oi", "olá", "bom dia", "boa tarde", "boa noite", "tudo bem?", "obrigado".
- "ajuda": APENAS perguntas sobre como usar o assistente ou sobre o que é natureza de despesa, como "como faço para buscar?", "como funciona?", "o que é natureza de despesa?", "me ajuda a usar isso", "onde digito o código?".
- "busca": TODO o resto. Qualquer descrição de gasto, material, serviço ou código, inclusive palavras isoladas, termos desconhecidos e texto sem sentido.

Regras da intenção:
- Se a mensagem não for claramente um cumprimento, NÃO use "saudacao".
- Se a mensagem não for claramente uma pergunta sobre o funcionamento ou sobre o conceito, NÃO use "ajuda".
- Na dúvida entre "busca" e as outras intenções, use "busca".

Para "busca", extraia o termo central que descreve o gasto e descarte verbos de intenção e palavras funcionais ("quero", "preciso", "comprar", "adquirir", "de", "para").
Preserve um termo curto e claro como o usuário digitou (por exemplo, "gasolina" continua "gasolina"; "zqxjvkw" continua "zqxjvkw").
Corrija erros de ortografia evidentes e use minúsculas com acentos corretos (por exemplo, "cerviso de limpesa" vira "serviço de limpeza").
Use no máximo 3 palavras e mantenha o sentido da mensagem.
Nunca invente um termo que não esteja relacionado à mensagem.

Exemplos:
- "oi" -> {"intencao": "saudacao", "termo_busca": ""}
- "bom dia" -> {"intencao": "saudacao", "termo_busca": ""}
- "como faço para buscar?" -> {"intencao": "ajuda", "termo_busca": ""}
- "o que é natureza de despesa?" -> {"intencao": "ajuda", "termo_busca": ""}
- "gasolina" -> {"intencao": "busca", "termo_busca": "gasolina"}
- "quero comprar gasolina" -> {"intencao": "busca", "termo_busca": "gasolina"}
- "zqxjvkw" -> {"intencao": "busca", "termo_busca": "zqxjvkw"}
- "teste" -> {"intencao": "busca", "termo_busca": "teste"}

Para "saudacao" e "ajuda", use termo_busca vazio.`;

return [{
  json: {
    chat_input: chatInput,
    request_body: {
      model: 'qwen3:4b',
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: chatInput },
      ],
      stream: false,
      think: false,
      format: {
        type: 'object',
        properties: {
          intencao: { type: 'string', enum: ['busca', 'saudacao', 'ajuda'] },
          termo_busca: { type: 'string' },
        },
        required: ['intencao', 'termo_busca'],
        additionalProperties: false,
      },
      options: { temperature: 0, num_ctx: 4096 },
      keep_alive: '30m',
    },
  },
}];

// Turn the extract/route model's reply into an intenção and a single termo_busca.
const userText = String($('Build Chat Request').first().json.chat_input ?? '').trim();
const content = $json?.message?.content ?? $json?.output ?? '';
const raw = typeof content === 'string' ? content : JSON.stringify(content ?? '');

let parsed = null;
const first = raw.indexOf('{');
const last = raw.lastIndexOf('}');
if (first !== -1 && last > first) {
  try {
    parsed = JSON.parse(raw.slice(first, last + 1));
  } catch (error) {
    // fall through to the plain-text branch
  }
}

let term = parsed ? String(parsed?.termo_busca ?? '') : '';
if (!parsed) {
  term = raw.split(/\r?\n/).map((line) => line.trim()).filter(Boolean)[0] || '';
}
term = term.replace(/^termo[_\s-]?busca\s*[:=]\s*/i, '');
term = term.replace(/^["'`\u201c\u201d]+|["'`\u201c\u201d]+$/g, '').trim();

// Anything the model does not explicitly route as greeting/help is a search.
const normalized = String(parsed?.intencao ?? '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const intencao = normalized === 'saudacao' || normalized === 'ajuda' ? normalized : 'busca';
if (intencao !== 'busca') {
  term = '';
} else if (!term) {
  term = userText;
}

return [{ json: { intencao, termo_busca: term, chat_input: userText } }];

// Greeting and help are answered without retrieval: fixed Portuguese text only.
const ORIENTATION = 'Escreva palavras chave para a natureza de despesa ou código parcial ou integral\nExemplos: Gasolina, Material gráfico, Serviço de limpeza predial Pessoa Física, Serviços de terceiros Pessoa Jurídica, Software de Gestão, Reforma de Telhado, Papel, 3.3.90.30, 339030, 339 ...';
const HELP = 'Digite uma palavra-chave ou o código da natureza de despesa e eu faço a busca para você.';

const intencao = String($json.intencao ?? '').trim();
const reply = intencao === 'ajuda' ? HELP + '\n\n' + ORIENTATION : ORIENTATION;

return [{ json: { output: reply, text: reply } }];

// Join the query embedding with the tunable search configuration.
const config = $('Search Config (floor, Top-K)').first().json;
const embeddings = $json.embeddings;

if (!Array.isArray(embeddings) || !Array.isArray(embeddings[0]) || embeddings[0].length === 0) {
  throw new Error('Ollama returned no embedding for the search term.');
}

const floor = Number(config.similarity_floor);
const topK = Number(config.top_k);
if (!Number.isFinite(floor) || !Number.isInteger(topK) || topK < 1) {
  throw new Error('Search configuration is invalid: similarity_floor must be a number and top_k a positive integer.');
}

return [{
  json: {
    termo_busca: String($('Parse Termo').first().json?.termo_busca ?? ''),
    similarity_floor: floor,
    top_k: topK,
    vector_literal: JSON.stringify(embeddings[0].map(Number)),
  },
}];

// Render the reply deterministically: result rows never reach a model.
const reply = String($json.reply ?? '');

return [{ json: { output: reply, text: reply } }];

// Decide the reply shape from the Candidatos: none, one to seven, or too many.
// Clustering is deterministic and only short Descrição/Título names ever reach
// the naming model (ADR-0003).

const rows = $input.all()
  .map((item) => item.json)
  .filter((row) => row && row.codigo);

const PASSO3_SEPARATOR = '-'.repeat(48);
const NOT_FOUND = 'Não encontrei esta despesa no banco de dados. Tente descrever de outra forma, como o tipo do material ou serviço.';
const CLOSING = 'Algum corresponde ao que você precisa? Posso refinar a busca.';
const MAX_BLOCKS = 7;
const MAX_ASSUNTOS = 5;
// Below this silhouette a grouping has no genuine structure, so every
// Candidato is shown instead of forcing arbitrary Assuntos.
const MIN_SILHOUETTE = 0.1;
const KMEANS_SEED = 0x5eed;
const MAX_ITERATIONS = 100;

const cappedNotice = (limit) => `Os resultados foram limitados aos ${limit} mais relevantes. Refine o termo de busca para ver outras opções.`;

const renderBlock = (row) => [
  PASSO3_SEPARATOR,
  `Código: ${row.codigo ?? '-'}`,
  `Descrição: ${row.descricao ?? '-'}`,
  `Título: ${row.titulo || '-'}`,
  `Detalhe: ${row.detalhe || '-'}`,
  PASSO3_SEPARATOR,
].join('\n');

// The stored offer needs the session and the search term; both retrieval paths
// reach this node, so resolve the term from whichever branch actually ran.
const readTermoBusca = () => {
  if ($('Build Vector Literal').isExecuted) {
    return String($('Build Vector Literal').first().json?.termo_busca ?? '').trim();
  }
  if ($('Build Code Query').isExecuted) {
    return String($('Build Code Query').first().json?.codigo_digits ?? '').trim();
  }
  return '';
};
const termoBusca = readTermoBusca();
const sessionId = String($('When chat message received').first().json?.sessionId ?? '').trim();
const topK = Number($('Search Config (floor, Top-K)').first().json?.top_k);
// Retrieval is capped when it returns exactly Top-K rows; the reply says so.
const capped = Number.isInteger(topK) && topK > 0 && rows.length >= topK;

const emit = (reply) => [{ json: { needs_assuntos: false, capped, top_k: topK, reply, output: reply, text: reply, session_id: sessionId, termo_busca: termoBusca } }];
const renderAll = (candidates) => {
  const blocks = candidates.map(renderBlock).join('\n\n');
  const notice = capped ? cappedNotice(topK) + '\n\n' : '';
  return blocks + '\n\n' + notice + CLOSING;
};

if (rows.length === 0) return emit(NOT_FOUND);
if (rows.length <= MAX_BLOCKS) return emit(renderAll(rows));

const parseEmbedding = (value) => {
  const parsed = Array.isArray(value) ? value : JSON.parse(String(value ?? '[]'));
  if (!Array.isArray(parsed) || parsed.length === 0) {
    throw new Error('Candidato sem embedding válido para o agrupamento.');
  }
  return parsed.map(Number);
};

const normalize = (vector) => {
  let norm = 0;
  for (const value of vector) norm += value * value;
  norm = Math.sqrt(norm);
  if (!Number.isFinite(norm) || norm === 0) {
    throw new Error('Candidato com embedding inválido para o agrupamento.');
  }
  return vector.map((value) => value / norm);
};

const distance = (a, b) => {
  let dot = 0;
  for (let index = 0; index < a.length; index += 1) dot += a[index] * b[index];
  return 1 - dot;
};

// mulberry32: a fixed seed makes Assunto grouping reproducible across runs.
const makeRandom = (seed) => {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
};

const initCenters = (vectors, k, random) => {
  const centers = [vectors[Math.floor(random() * vectors.length)]];
  while (centers.length < k) {
    const weights = vectors.map((vector) => {
      const nearest = Math.min(...centers.map((center) => distance(vector, center)));
      return nearest * nearest;
    });
    const total = weights.reduce((sum, weight) => sum + weight, 0);
    if (!Number.isFinite(total) || total === 0) return centers;
    let target = random() * total;
    let index = 0;
    while (index < weights.length - 1 && target > weights[index]) {
      target -= weights[index];
      index += 1;
    }
    centers.push(vectors[index]);
  }
  return centers;
};

const assign = (vectors, centers) => vectors.map((vector) => {
  let chosen = 0;
  let best = Infinity;
  centers.forEach((center, index) => {
    const candidate = distance(vector, center);
    if (candidate < best) {
      best = candidate;
      chosen = index;
    }
  });
  return chosen;
});

const kmeans = (vectors, k, random) => {
  const centers = initCenters(vectors, k, random);
  if (centers.length < k) return null;
  let labels = null;
  for (let iteration = 0; iteration < MAX_ITERATIONS; iteration += 1) {
    const next = assign(vectors, centers);
    if (labels && next.every((label, index) => label === labels[index])) break;
    labels = next;
    const sums = Array.from({ length: k }, () => new Array(vectors[0].length).fill(0));
    const counts = new Array(k).fill(0);
    labels.forEach((label, index) => {
      counts[label] += 1;
      const vector = vectors[index];
      for (let dimension = 0; dimension < vector.length; dimension += 1) {
        sums[label][dimension] += vector[dimension];
      }
    });
    for (let cluster = 0; cluster < k; cluster += 1) {
      if (!counts[cluster]) return null;
      centers[cluster] = normalize(sums[cluster]);
    }
  }
  return labels;
};

const pairwiseDistances = (vectors) => vectors.map((a) => vectors.map((b) => distance(a, b)));

const silhouette = (distances, labels) => {
  let total = 0;
  for (let index = 0; index < labels.length; index += 1) {
    const own = labels[index];
    let ownSum = 0;
    let ownCount = 0;
    const others = new Map();
    for (let other = 0; other < labels.length; other += 1) {
      if (other === index) continue;
      if (labels[other] === own) {
        ownSum += distances[index][other];
        ownCount += 1;
      } else {
        const entry = others.get(labels[other]) || [0, 0];
        entry[0] += distances[index][other];
        entry[1] += 1;
        others.set(labels[other], entry);
      }
    }
    if (!ownCount || others.size === 0) return -Infinity;
    let nearest = Infinity;
    for (const [sum, count] of others.values()) {
      nearest = Math.min(nearest, sum / count);
    }
    const a = ownSum / ownCount;
    const denominator = Math.max(a, nearest);
    total += denominator === 0 ? 0 : (nearest - a) / denominator;
  }
  return total / labels.length;
};

const chooseClustering = (vectors) => {
  const maxK = Math.min(MAX_ASSUNTOS, Math.floor(vectors.length / 2));
  if (maxK < 2) return null;
  const distances = pairwiseDistances(vectors);
  let best = null;
  for (let k = 2; k <= maxK; k += 1) {
    const labels = kmeans(vectors, k, makeRandom(KMEANS_SEED + k));
    if (!labels) continue;
    const sizes = new Array(k).fill(0);
    labels.forEach((label) => { sizes[label] += 1; });
    if (sizes.some((size) => size < 2)) continue;
    const score = silhouette(distances, labels);
    if (!Number.isFinite(score)) continue;
    if (!best || score > best.score + 1e-12) best = { score, labels };
  }
  if (!best || best.score < MIN_SILHOUETTE) return null;
  return { ...best, distances };
};

const clusterRows = (vectors, clustering) => {
  const groups = Array.from({ length: Math.max(...clustering.labels) + 1 }, () => []);
  clustering.labels.forEach((label, index) => groups[label].push(index));
  return groups.map((indices) => {
    const local = indices.map((row) => indices.map((column) => clustering.distances[row][column]));
    const sums = local.map((row) => row.reduce((sum, value) => sum + value, 0));
    let medoidPos = 0;
    for (let position = 1; position < sums.length; position += 1) {
      if (sums[position] < sums[medoidPos]) medoidPos = position;
    }
    const ordered = indices
      .map((row, position) => ({ row, distance: local[medoidPos][position] }))
      .sort((a, b) => a.distance - b.distance || a.row - b.row)
      .slice(0, 3)
      .map((entry) => rows[entry.row]);
    return {
      linha_ids: indices.map((row) => rows[row].id),
      medoid: rows[indices[medoidPos]],
      representatives: ordered,
    };
  });
};

let vectors;
try {
  vectors = rows.map((row) => normalize(parseEmbedding(row.embedding)));
} catch {
  return emit(renderAll(rows));
}

const clustering = chooseClustering(vectors);
if (!clustering) {
  return emit(renderAll(rows));
}

const groups = clusterRows(vectors, clustering);
const describe = (row) => [row.descricao, row.titulo]
  .map((value) => String(value ?? '').trim())
  .filter(Boolean)
  .join(' | ');

const prompt = groups.map((group, index) => [
  `Assunto ${index + 1}:`,
  ...group.representatives.map((row) => `- ${describe(row) || '(sem descrição)'}`),
].join('\n')).join('\n\n');

const SYSTEM_PROMPT = `Você nomeia assuntos de naturezas de despesa públicas brasileiras.

Receberá vários assuntos, cada um com algumas descrições de linhas. Dê a cada assunto um rótulo curto, em português, com 2 a 4 palavras, em forma de substantivo (por exemplo: "Combustíveis", "Material de limpeza", "Serviços gráficos"). Os rótulos devem ser distintos entre si e não podem repetir o número do assunto.

Responda somente com JSON no formato {"assuntos": [{"indice": 1, "rotulo": "..."}]}, com um item para cada assunto recebido, na mesma ordem.`;

const namingModel = String($('When chat message received').first().json?.naming_model ?? '').trim() || 'qwen3:4b';

const naming_request = {
  model: namingModel,
  messages: [
    { role: 'system', content: SYSTEM_PROMPT },
    { role: 'user', content: prompt },
  ],
  stream: false,
  think: false,
  format: {
    type: 'object',
    properties: {
      assuntos: {
        type: 'array',
        minItems: groups.length,
        maxItems: groups.length,
        items: {
          type: 'object',
          properties: {
            indice: { type: 'integer' },
            rotulo: { type: 'string' },
          },
          required: ['indice', 'rotulo'],
          additionalProperties: false,
        },
      },
    },
    required: ['assuntos'],
    additionalProperties: false,
  },
  options: { temperature: 0, num_ctx: 4096 },
  keep_alive: '30m',
};

return [{
  json: {
    needs_assuntos: true,
    session_id: sessionId,
    termo_busca: termoBusca,
    capped,
    top_k: topK,
    assuntos: groups.map((group) => ({
      linha_ids: group.linha_ids,
      fallback_label: group.medoid.descricao,
    })),
    naming_request,
    reply: '',
    output: '',
    text: '',
  },
}];

// Turn the naming call into lettered choices. A failed or malformed call falls
// back to each Assunto's medoid Descrição; the reply is always deterministic.

const groups = $('Build Assuntos').first().json.assuntos ?? [];
const content = $json?.message?.content ?? '';
const raw = typeof content === 'string' ? content : JSON.stringify(content ?? '');

let parsed = null;
const first = raw.indexOf('{');
const last = raw.lastIndexOf('}');
if (first !== -1 && last > first) {
  try {
    parsed = JSON.parse(raw.slice(first, last + 1));
  } catch {
    parsed = null;
  }
}

const named = new Map();
if (parsed && Array.isArray(parsed.assuntos)) {
  for (const item of parsed.assuntos) {
    const index = Number(item?.indice);
    const label = String(item?.rotulo ?? '').trim();
    if (Number.isInteger(index) && index >= 1 && index <= groups.length && label) {
      named.set(index, label);
    }
  }
}

const normalizeLabel = (label) => String(label ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase();

const sanitizeLabel = (label) => {
  let text = String(label ?? '').replace(/\s+/g, ' ').trim();
  text = text.replace(/^["'`\u201c\u201d]+|["'`\u201c\u201d]+$/g, '');
  text = text.replace(/^\d+\s*[.)\-–—:]\s*/, '');
  text = text.replace(/^[A-Za-z]\s*[.)\-–—:]\s*/, '');
  text = text.replace(/[.;:,]+$/, '').trim();
  if (text.length > 60) {
    text = text.slice(0, 60).replace(/\s+\S*$/, '').trim();
  }
  return text;
};

const used = new Set();
const assuntos = groups.map((group, index) => {
  const modelLabel = sanitizeLabel(named.get(index + 1));
  const base = modelLabel || sanitizeLabel(group.fallback_label) || 'Assunto';
  let label = base;
  let suffix = 0;
  while (used.has(normalizeLabel(label))) {
    suffix += 1;
    label = `${base} · ${suffix}`;
  }
  used.add(normalizeLabel(label));
  return {
    letter: String.fromCharCode(65 + index),
    label,
    count: Array.isArray(group.linha_ids) ? group.linha_ids.length : 0,
    linha_ids: group.linha_ids,
  };
});

// Persist only labels and Linha ids: the rows themselves are never stored, and
// expansion re-queries them from the authoritative table (ADR-0003). The clock
// is last activity, refreshed by every Seleção.
const groupData = $('Build Assuntos').first().json;
const sessionId = String(groupData?.session_id ?? '').trim();
if (sessionId && assuntos.length > 0) {
  const store = $getWorkflowStaticData('global');
  if (!store.desambiguacoes || typeof store.desambiguacoes !== 'object' || Array.isArray(store.desambiguacoes)) {
    store.desambiguacoes = {};
  }
  store.desambiguacoes[sessionId] = {
    last_activity_at: Date.now(),
    termo_busca: String(groupData?.termo_busca ?? ''),
    assuntos: assuntos.map((assunto) => ({
      label: assunto.label,
      linha_ids: assunto.linha_ids,
    })),
  };
}

const choices = assuntos
  .map((assunto) => `${assunto.letter} — ${assunto.label} (${assunto.count})`)
  .join('\n');
const paragraphs = [
  `Encontrei muitos resultados para essa busca. Separei os candidatos em assuntos:\n\n${choices}`,
];
if (groupData?.capped) {
  paragraphs.push(`Os resultados foram limitados aos ${Number(groupData?.top_k)} mais relevantes. Refine o termo de busca para ver outras opções.`);
}
paragraphs.push('Responda com a letra (A, B, C), o ordinal (primeiro, segundo, terceiro) ou o nome do assunto. Para uma busca diferente, digite um novo termo.');
const reply = paragraphs.join('\n\n');

return [{ json: { output: reply, text: reply, assuntos } }];

// Load the pending Desambiguação for this chat session and decide whether the
// message is a Seleção. A Seleção expands one Assunto and consumes it; the
// Desambiguação survives until every Assunto is consumed, a new Termo de busca
// arrives, or the session goes idle past its time limit.

const IDLE_TTL_MS = 10 * 60 * 1000;

const chatInput = String($json.chatInput ?? '').trim();
const sessionId = String($json.sessionId ?? '').trim();
const configuredTtl = Number($json.offer_ttl_ms);
const ttl = Number.isFinite(configuredTtl) && configuredTtl > 0 ? configuredTtl : IDLE_TTL_MS;
const now = Date.now();

const store = $getWorkflowStaticData('global');
if (!store.desambiguacoes || typeof store.desambiguacoes !== 'object' || Array.isArray(store.desambiguacoes)) {
  store.desambiguacoes = {};
}
const desambiguacoes = store.desambiguacoes;

// Expired Desambiguações are never used, and pruning keeps the static data
// small. The clock is last activity, so an engaged session never expires.
for (const key of Object.keys(desambiguacoes)) {
  const lastActivity = Number(desambiguacoes[key]?.last_activity_at);
  if (!Number.isFinite(lastActivity) || now - lastActivity >= IDLE_TTL_MS) delete desambiguacoes[key];
}

const desambiguacao = sessionId ? desambiguacoes[sessionId] : undefined;
const assuntos = Array.isArray(desambiguacao?.assuntos) ? desambiguacao.assuntos : [];
const lastActivityAt = Number(desambiguacao?.last_activity_at);
const isDesambiguacaoValid = Number.isFinite(lastActivityAt)
  && now - lastActivityAt < ttl
  && assuntos.length > 0
  && assuntos.every((assunto) => {
    const ids = Array.isArray(assunto?.linha_ids) ? assunto.linha_ids : [];
    return Boolean(String(assunto?.label ?? '').trim())
      && ids.length > 0
      && ids.every((id) => Number.isInteger(Number(id)) && Number(id) > 0);
  });

const canonical = (text) => String(text ?? '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/[^a-z0-9]+/g, ' ')
  .trim();

const ORDINAIS = {
  primeiro: 0, primeira: 0,
  segundo: 1, segunda: 1,
  terceiro: 2, terceira: 2,
  quarto: 3, quarta: 3,
  quinto: 4, quinta: 4,
};

const resolveChoice = (value) => {
  if (!value) return -1;
  if (/^[a-z]$/.test(value)) return value.charCodeAt(0) - 97;
  if (/^[1-5]$/.test(value)) return Number(value) - 1;
  if (Object.prototype.hasOwnProperty.call(ORDINAIS, value)) return ORDINAIS[value];
  return assuntos.findIndex((assunto) => canonical(assunto?.label) === value);
};

// A Seleção is a bare option token, an ordinal, "opção x", or an Assunto label.
// Anything else falls through to a fresh search, never to a model-based guess.
const message = canonical(chatInput);
const withOption = message.match(/^opcao\s+(.+)$/);
const choice = message ? resolveChoice(withOption ? withOption[1] : message) : -1;

if (isDesambiguacaoValid && choice >= 0 && choice < assuntos.length) {
  const chosen = assuntos[choice];
  // Consume this Assunto only; the rest stay on offer. Letters are positional,
  // so an Assunto is never removed from the array — re-selecting an expanded
  // one re-renders it and leaves the consumed set unchanged.
  if (!Number.isFinite(Number(chosen.expanded_at))) chosen.expanded_at = now;
  desambiguacao.last_activity_at = now;

  const remaining = assuntos
    .map((assunto, index) => ({ assunto, index }))
    .filter(({ assunto }) => !Number.isFinite(Number(assunto.expanded_at)))
    .map(({ assunto, index }) => ({
      letter: String.fromCharCode(65 + index),
      label: String(assunto.label ?? ''),
      count: Array.isArray(assunto.linha_ids) ? assunto.linha_ids.length : 0,
    }));

  // The Desambiguação ends on its own once every Assunto has been expanded.
  if (remaining.length === 0) delete desambiguacoes[sessionId];

  return [{
    json: {
      is_selecao: true,
      session_id: sessionId,
      chatInput,
      selected_ids: chosen.linha_ids.map(Number),
      remaining,
    },
  }];
}

// Any message that is not a Seleção is a new Termo de busca and discards the
// pending Desambiguação.
if (sessionId) delete desambiguacoes[sessionId];
return [{
  json: {
    is_selecao: false,
    session_id: sessionId,
    chatInput,
  },
}];

// Keep only the Linha ids of the chosen Assunto; they are re-queried below.
const raw = Array.isArray($json.selected_ids) ? $json.selected_ids : [];
const ids = raw
  .map((value) => Number(value))
  .filter((value) => Number.isInteger(value) && value > 0);

if (ids.length === 0) {
  throw new Error('Seleção sem Linhas para expandir.');
}

return [{ json: { linha_ids: ids.join(',') } }];

// Render the expanded Assunto's Linhas exactly like the PASSO 3 blocks. The
// rows come from the table, re-queried by id, never from the stored offer.
const rows = $input.all()
  .map((item) => item.json)
  .filter((row) => row && row.codigo);

const SEPARATOR = '-'.repeat(48);
const CLOSING = 'Algum corresponde ao que você precisa? Posso refinar a busca.';
const NOT_FOUND = 'Não encontrei esta despesa no banco de dados. Tente descrever de outra forma, como o tipo do material ou serviço.';
const REMAINING_LEAD = 'Ainda posso abrir outros assuntos:';
const REMAINING_HINT = 'Responda com a letra ou o nome do assunto.';

// Assuntos restantes live in the Desambiguação, not in this branch's SQL rows.
const remaining = Array.isArray($('Load Desambiguação').first().json?.remaining)
  ? $('Load Desambiguação').first().json.remaining
  : [];
const remainingBlock = remaining.length === 0 ? '' : [
  REMAINING_LEAD,
  ...remaining.map((assunto) => `${assunto.letter} — ${assunto.label} (${assunto.count})`),
].join('\n') + '\n\n' + REMAINING_HINT;

const renderBlock = (row) => [
  SEPARATOR,
  `Código: ${row.codigo ?? '-'}`,
  `Descrição: ${row.descricao ?? '-'}`,
  `Título: ${row.titulo || '-'}`,
  `Detalhe: ${row.detalhe || '-'}`,
  SEPARATOR,
].join('\n');

if (rows.length === 0) {
  return [{ json: { output: NOT_FOUND, text: NOT_FOUND } }];
}

const reply = [rows.map(renderBlock).join('\n\n'), CLOSING, remainingBlock]
  .filter(Boolean)
  .join('\n\n');
return [{ json: { output: reply, text: reply } }];
